// خواندن شناسه آخرین پیام پردازش‌شده از حافظه دائمی Workflow
// این مقدار بین اجراهای مختلف حفظ می‌شود و از پردازش تکراری پیام‌ها جلوگیری می‌کند
const staticData = $getWorkflowStaticData('global');

return [{ json: { offset: staticData.telegramOffset || 0 } }];

// استخراج پیام‌های متنی و به‌روزرسانی نشانگر
const staticData = $getWorkflowStaticData('global');
const response = items[0].json;
const updates = response.result || [];
const output = [];

for (const update of updates) {
  // نشانگر همیشه جلو می‌رود، حتی برای آپدیت‌هایی که پیام متنی نیستند
  staticData.telegramOffset = update.update_id + 1;

  const message = update.message;
  if (!message || !message.text) continue;

  output.push({
    json: {
      chatId: message.chat.id,
      text: message.text,
      firstName: message.from.first_name || '',
    },
  });
}

// اگر پیام جدیدی نبود، آرایه خالی برمی‌گردد و اجرای Workflow همین‌جا متوقف می‌شود
return output;

